    IntStream.range(0, 10_000).forEach(i -> {
        executor.submit(() -> {
            Thread.sleep(Duration.ofSeconds(1)); // NO bloquea el hilo del OS; desmonta el Virtual Thread del Carrier Thread
            return i;
        });
    });
}

